CSS = '\n<style>\n:root{--obs-navy:#072146;--obs-blue:#1464a5;--obs-teal:#02a5a5;--obs-line:#e0e8ef;--obs-bg:#f4f7fa}\nhtml,body,[data-testid="stAppViewContainer"]{font-family:Arial,sans-serif;background:#f4f7fa;color:#173455}\n.stApp{background:#f4f7fa;color:#173455}\n.block-container{max-width:100%;width:100%;padding:4.5rem 2.75rem 3rem}\nh1,h2,h3{color:#072146;font-family:Arial,sans-serif;letter-spacing:-.03em}h1{font-size:2rem}h2{font-size:1.35rem}h3{font-size:1.1rem}\n[data-testid="stSidebar"]{background:#072146;border-right:0;}\n[data-testid="stSidebar"] [data-testid="stSidebarContent"]{padding-top:1rem}\n[data-testid="stSidebar"] p,[data-testid="stSidebar"] label,[data-testid="stSidebar"] small{color:#b0c9e2!important}\n[data-testid="stSidebar"] [data-testid="stRadio"] label{padding:9px 6px;border-radius:4px}\n[data-testid="stSidebar"] [data-testid="stRadio"] label:has(input:checked){background:#17416d;box-shadow:inset 3px 0 #4bd3cf}\n[data-testid="stSidebar"] [data-testid="stRadio"] label:has(input:checked) p{color:white!important}\n[data-testid="stSidebar"] [data-testid="stTextInput"] input{background:white!important;color:#072146!important}\n[data-testid="stSidebar"] button{background:#17416d;color:white;border-color:#315170}\n.obs-brand{color:white;font-size:clamp(23px,2.1vw,28px);white-space:nowrap;font-weight:700;letter-spacing:-1.4px;margin:5px 0 6px}.obs-brand-sub{font-size:9px;letter-spacing:2px;color:#a5c9eb;margin-bottom:28px}\n.obs-head{display:flex;justify-content:space-between;gap:12px;align-items:center;flex-wrap:wrap;border-bottom:1px solid #e0e8ef;padding:0 0 20px;margin-bottom:24px}.obs-crumb{font-size:10px;letter-spacing:1.4px;color:#647990}.obs-badge{font-size:10px;letter-spacing:1px;background:#e6f3f4;color:#257978;padding:8px 12px;border-radius:3px}\n[data-testid="stMetric"]{background:white;border:1px solid #e0e8ef;border-radius:5px;padding:14px 20px;box-shadow:0 2px 5px #07214604}\n[data-testid="stMetricValue"]{color:#072146;font-size:28px}\n[data-testid="stVerticalBlockBorderWrapper"]{background:white;border-color:#e0e8ef!important;border-radius:5px}\n[data-testid="stCaptionContainer"]{color:#647990}\n.stButton>button,.stDownloadButton>button{border-radius:4px;border:1px solid #dce5ed;color:#1464a5}\n.stButton>button:hover,.stDownloadButton>button:hover{border-color:#02a5a5;color:#072146;background:#e6f3f4}\n[data-testid="stSelectbox"]>div>div,[data-testid="stTextInput"] input{background:white;color:#072146}\n@media(max-width:800px){.block-container{padding:4.5rem 1rem 3rem}.obs-head{margin-bottom:16px}}\n</style>'
